`timescale 1ns/1ps

// QNSC wrapper of m_qnsc_p_bus: the QSoC P_BUS (APB4 peripheral bus).
// Spec: QNSC_PBUS_MAS on the team SharePoint.
//
// Edit this .src.sv, then `make wrap BLOCK=pbus`: emacs verilog-mode expands
// the AUTO comments and writes rtl/m_qnsc_wrap_pbus.sv, the file pbus.f compiles.
// Template functions: doc/rules/EMACS_quick_guide.pdf.
//
// The core is m_qnsc_p_bus, generated by APB-BUS-Generator from
// util/gen/p_bus/p_bus.xlsx (recipe util/gen/p_bus/gen.sh). One master, the
// AXI2APB bridge, 18-bit address (contract meta.pbus_paddr_width); fourteen
// slaves APB_M0..M13, 14-bit offset each (meta.apb_paddr_width). There is no
// bridge: both sides already speak APB.
//
// What this wrapper does, and nothing else:
//   - names the ports by Naming Rule 3.3: the input side is the APB port the
//     bridge drives, i_bus_apb_s_0_* / o_bus_apb_s_0_*; slave n is
//     o_bus_apb_m_<n>_* / i_bus_apb_m_<n>_*, n = the contract port APB_Mn;
//   - ties i_clk/i_rstn: with one master every arbiter is plain assignments
//     and the decoder is combinational, so the router has no flip-flop and
//     P_BUS has no clock or reset port (QNSC_PBUS_MAS);
//   - ties the generator's sideband inputs (pprot, protect_en, slverr_en) and
//     leaves their outputs open: AXI2APB drives no PPROT, and each slave's
//     PPROT is tied in design/top (QNSC_PBUS_MAS, "No PPROT through P_BUS").
//
// A wrapper is IP (design/README.md, "Shared numbers: who may use qnsc_pkg"):
// no import, no parameter. The address map lives in the generated core, not here.

module m_qnsc_wrap_pbus
(
//---------------------------------------------------------------
// APB from the AXI2APB bridge (P_BUS is its slave): paddr[17:0]
//---------------------------------------------------------------
/*AUTOINPUT("^i_bus_apb_s_0_")*/
/*AUTOOUTPUT("^o_bus_apb_s_0_")*/

//---------------------------------------------------------------
// APB to the slaves: paddr[13:0], the offset in the 16 KiB slot
//---------------------------------------------------------------
// APB_M0  SCRC     0x8000_0000
/*AUTOOUTPUT("^o_bus_apb_m_0_")*/
/*AUTOINPUT("^i_bus_apb_m_0_")*/
// APB_M1  SYSCSR   0x8000_4000
/*AUTOOUTPUT("^o_bus_apb_m_1_")*/
/*AUTOINPUT("^i_bus_apb_m_1_")*/
// APB_M2  WDT      0x8000_8000
/*AUTOOUTPUT("^o_bus_apb_m_2_")*/
/*AUTOINPUT("^i_bus_apb_m_2_")*/
// APB_M3  GPIO_0   0x8000_C000
/*AUTOOUTPUT("^o_bus_apb_m_3_")*/
/*AUTOINPUT("^i_bus_apb_m_3_")*/
// APB_M4  GPIO_1   0x8001_0000
/*AUTOOUTPUT("^o_bus_apb_m_4_")*/
/*AUTOINPUT("^i_bus_apb_m_4_")*/
// APB_M5  GPIO_2   0x8001_4000
/*AUTOOUTPUT("^o_bus_apb_m_5_")*/
/*AUTOINPUT("^i_bus_apb_m_5_")*/
// APB_M6  TIMER_0  0x8001_8000
/*AUTOOUTPUT("^o_bus_apb_m_6_")*/
/*AUTOINPUT("^i_bus_apb_m_6_")*/
// APB_M7  TIMER_1  0x8001_C000
/*AUTOOUTPUT("^o_bus_apb_m_7_")*/
/*AUTOINPUT("^i_bus_apb_m_7_")*/
// APB_M8  UART_0   0x8002_0000
/*AUTOOUTPUT("^o_bus_apb_m_8_")*/
/*AUTOINPUT("^i_bus_apb_m_8_")*/
// APB_M9  UART_1   0x8002_4000
/*AUTOOUTPUT("^o_bus_apb_m_9_")*/
/*AUTOINPUT("^i_bus_apb_m_9_")*/
// APB_M10 SPI      0x8002_8000
/*AUTOOUTPUT("^o_bus_apb_m_10_")*/
/*AUTOINPUT("^i_bus_apb_m_10_")*/
// APB_M11 I2C      0x8002_C000
/*AUTOOUTPUT("^o_bus_apb_m_11_")*/
/*AUTOINPUT("^i_bus_apb_m_11_")*/
// APB_M12 PWM      0x8003_0000
/*AUTOOUTPUT("^o_bus_apb_m_12_")*/
/*AUTOINPUT("^i_bus_apb_m_12_")*/
// APB_M13 DMA_CFG  0x8003_4000
/*AUTOOUTPUT("^o_bus_apb_m_13_")*/
/*AUTOINPUT("^i_bus_apb_m_13_")*/
// APB_M14, APB_M15 (0x8003_8000 - 0x8003_FFFF): no port; the core answers
// PREADY = 1, PSLVERR = 1, PRDATA = 0.

//---------------------------------------------------------------
// Others -- must stay empty once the template below is complete
//---------------------------------------------------------------
/*AUTOINOUT*/
/*AUTOINPUT*/
/*AUTOOUTPUT*/
);

/*AUTOWIRE*/

/*AUTO_LISP(setq verilog-auto-inout-ignore-regexp
