// The generator names a port <dir>_<signal>_<master|slave>; the rules below
// move the block name to the contract port: i_paddr_axi2apb -> i_bus_apb_s_0_paddr,
// o_psel_uart_0 -> o_bus_apb_m_8_psel. First match wins; [] keeps the width.
/* m_qnsc_p_bus AUTO_TEMPLATE(
    .i_clk                               (1'b0),
    .i_rstn                              (1'b1),
    .i_\(protect_en\|slverr_en\)_axi2apb (1'b0),
    .i_pprot_axi2apb                     (3'b000),
    .o_\(protect_en\|slverr_en\|pprot\)_.* (),
    .\([io]\)_\(p[a-z]+\)_axi2apb        (\1_bus_apb_s_0_\2[]),
    .\([io]\)_\(p[a-z]+\)_scrc           (\1_bus_apb_m_0_\2[]),
    .\([io]\)_\(p[a-z]+\)_syscsr         (\1_bus_apb_m_1_\2[]),
    .\([io]\)_\(p[a-z]+\)_wdt            (\1_bus_apb_m_2_\2[]),
    .\([io]\)_\(p[a-z]+\)_gpio_0         (\1_bus_apb_m_3_\2[]),
    .\([io]\)_\(p[a-z]+\)_gpio_1         (\1_bus_apb_m_4_\2[]),
    .\([io]\)_\(p[a-z]+\)_gpio_2         (\1_bus_apb_m_5_\2[]),
    .\([io]\)_\(p[a-z]+\)_timer_0        (\1_bus_apb_m_6_\2[]),
    .\([io]\)_\(p[a-z]+\)_timer_1        (\1_bus_apb_m_7_\2[]),
    .\([io]\)_\(p[a-z]+\)_uart_0         (\1_bus_apb_m_8_\2[]),
    .\([io]\)_\(p[a-z]+\)_uart_1         (\1_bus_apb_m_9_\2[]),
    .\([io]\)_\(p[a-z]+\)_spi            (\1_bus_apb_m_10_\2[]),
    .\([io]\)_\(p[a-z]+\)_i2c            (\1_bus_apb_m_11_\2[]),
    .\([io]\)_\(p[a-z]+\)_pwm            (\1_bus_apb_m_12_\2[]),
    .\([io]\)_\(p[a-z]+\)_dma_cfg        (\1_bus_apb_m_13_\2[]),
);
*/
m_qnsc_p_bus u_p_bus (/*AUTOINST*/);

endmodule
